import api from './api';

export const realChecklistService = {
  // Checklists
  getAll: () => api.get('/checklists'),
  getById: (id) => api.get(`/checklists/${id}`),
  create: (data) => api.post('/checklists', data),
  update: (id, data) => api.put(`/checklists/${id}`, data),
  delete: (id) => api.delete(`/checklists/${id}`),
  submit: (data) => api.post('/checklists/submit', data),

  // Áreas
  getAreas: () => api.get('/areas'),
  createArea: (data) => api.post('/areas', data),
  updateArea: (id, data) => api.put(`/areas/${id}`, data),
  deleteArea: (id) => api.delete(`/areas/${id}`),

  // Proyectos
  getProjects: () => api.get('/projects'),
  createProject: (data) => api.post('/projects', data),
  updateProject: (id, data) => api.put(`/projects/${id}`, data),
  deleteProject: (id) => api.delete(`/projects/${id}`),

  // Usuarios
  getUsers: () => api.get('/users'),
  createUser: (data) => api.post('/users', data),
  updateUser: (id, data) => api.put(`/users/${id}`, data),
  deleteUser: (id) => api.delete(`/users/${id}`),
};

export default realChecklistService;
